beforeExample:
import org.eclipse.core.resources.IMarker;
import org.eclipse.core.resources.IResource;

// Dummy classes for compilation context, as Eclipse types are not available directly.
// In a real Eclipse environment, these would be provided by JDT bundles.
class IMarker {
    public static final int SEVERITY_ERROR = 2;
}
interface IResource {
    int DEPTH_ZERO = 0;
    int findMaxProblemSeverity(String markerType, boolean includeSubtypes, int depth);
}

class Example {
    void foo(IResource res) throws Exception {
        int severity = res.findMaxProblemSeverity("org.eclipse.jdt.launching.jreContainerMarker", true, IResource.DEPTH_ZERO);
        if (severity == IMarker.SEVERITY_ERROR) {
            System.out.println("Error found.");
        }
    }
}

